package com.wird.companion;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.media.MediaPlayer;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.net.*;
import java.io.*;
import java.util.*;

/** Native Android screens; no WebView or HTML UI. */
public class MainActivity extends Activity {
 final int bg=0xffF2F3EF, dark=0xff102D29, green=0xff365C50, pale=0xffDFE8E0;
 LinearLayout root, content; TextView heading; android.content.SharedPreferences prefs;
 MediaPlayer player; String audioServer=""; String selectedReciter="محمد صديق المنشاوي";
 int surah=1, page=1; final String[] reciters={"محمد صديق المنشاوي","محمود خليل الحصري","سعد الغامدي","محمد أيوب","أحمد طالب بن حميد","علي جابر"};
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(dark);getWindow().setNavigationBarColor(dark);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);prefs=getSharedPreferences("wird",MODE_PRIVATE);page=prefs.getInt("page",1);selectedReciter=prefs.getString("reciter",reciters[0]);home();}
 GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
 TextView txt(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.RIGHT);t.setTextDirection(View.TEXT_DIRECTION_RTL);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
 void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(bg);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);setContentView(root);TextView bar=txt("وِرد   •   "+title,23,0xffF2F3EF,true);bar.setBackgroundColor(dark);bar.setPadding(24,30,24,30);root.addView(bar);ScrollView scroll=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(1);content.setPadding(22,22,22,24);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(dark);nav.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);String[] labels={"الرئيسية","المصحف","الاستماع","التفسير","الحِكم"};Runnable[] run={()->home(),()->mushaf(),()->audio(),()->tafsir(),()->wisdom()};for(int i=0;i<labels.length;i++){final int k=i;TextView v=txt(labels[i],12,Color.WHITE,false);v.setGravity(Gravity.CENTER);v.setPadding(1,19,1,19);nav.addView(v,new LinearLayout.LayoutParams(0,-2,1));v.setOnClickListener(w->run[k].run());}root.addView(nav);}
 void paragraph(String s){TextView t=txt(s,17,dark,false);t.setLineSpacing(8,1);t.setPadding(16,18,16,18);content.addView(t);}
 void card(String s){TextView t=txt(s,18,dark,false);t.setBackground(shape(pale,24));t.setPadding(20,22,20,22);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=15;content.addView(t,p);}
 void btn(String label,Runnable action){TextView b=txt(label,17,Color.WHITE,true);b.setGravity(Gravity.CENTER);b.setBackground(shape(green,22));b.setPadding(15,20,15,20);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=12;content.addView(b,p);b.setOnClickListener(v->action.run());}
 void inputNumber(String hint,int initial,java.util.function.IntConsumer change){EditText e=new EditText(this);e.setSingleLine(true);e.setInputType(2);e.setText(String.valueOf(initial));e.setHint(hint);content.addView(e);btn("اعتماد الرقم",()->{try{change.accept(Integer.parseInt(e.getText().toString()));}catch(Exception ex){toast("أدخل رقماً صحيحاً");}});}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void home(){base("رفيق الحفظ");Calendar c=Calendar.getInstance();int day=c.get(Calendar.YEAR)*1000+c.get(Calendar.DAY_OF_YEAR);int last=prefs.getInt("last",-100);int streak=prefs.getInt("streak",0);card("السلام عليك 🌿\nكل عودة إلى القرآن بداية طيبة.\n\nسلسلة الاستمرار: "+streak+" يوم\nصفحتك الحالية: "+page);btn("ابدأ جلسة خمس دقائق",()->timer());String[] prayers={"الفجر","الظهر","العصر","المغرب","العشاء"};for(int i=0;i<5;i++){final int n=i;boolean done=prefs.getBoolean("d"+day+"p"+i,false);btn((done?"✓ ":"○ ")+prayers[i]+" — "+new String[]{"تأسيس الصفحة الأولى","تسميع الأولى","تأسيس الثانية","تسميع الثانية","مراجعة قديمة"}[i],()->{prefs.edit().putBoolean("d"+day+"p"+n,true).apply();boolean all=true;for(int j=0;j<5;j++)if(!prefs.getBoolean("d"+day+"p"+j,false))all=false;if(all && last!=day){Calendar yesterday=Calendar.getInstance();yesterday.add(Calendar.DAY_OF_YEAR,-1);int prev=yesterday.get(Calendar.YEAR)*1000+yesterday.get(Calendar.DAY_OF_YEAR);int next=(last==prev)?streak+1:1;prefs.edit().putInt("last",day).putInt("streak",next).apply();}home();});}btn("أنجزت الصفحتين — انتقل للتاليتين",()->{page=Math.min(603,page+2);prefs.edit().putInt("page",page).apply();home();});paragraph("لا يُصفّر تاريخ إنجازك إذا فات يوم. السلسلة الحالية تتجدد عند العودة، وسنضيف لاحقاً أيام حماية.");}
 void timer(){base("خمس دقائق مع القرآن");TextView clock=txt("05:00",42,dark,true);clock.setGravity(Gravity.CENTER);content.addView(clock);long end=System.currentTimeMillis()+300000;Handler h=new Handler();Runnable[] r=new Runnable[1];r[0]=()->{long left=Math.max(0,end-System.currentTimeMillis());clock.setText(String.format(java.util.Locale.US,"%02d:%02d",left/60000,(left/1000)%60));if(left>0 && clock.getParent()!=null)h.postDelayed(r[0],1000);else if(left==0)toast("بارك الله في وقتك");};h.post(r[0]);btn("العودة للرئيسية",()->home());}
 void mushaf(){base("المصحف");card("صفحة مصحف المدينة: "+page+" من 604\nالنص يجلب من مصدر إلكتروني ويحتاج اتصالاً بالإنترنت.");btn("الصفحة السابقة",()->{page=Math.max(1,page-1);prefs.edit().putInt("page",page).apply();mushaf();});btn("الصفحة التالية",()->{page=Math.min(604,page+1);prefs.edit().putInt("page",page).apply();mushaf();});btn("تحميل آيات الصفحة",()->loadPage());}
 interface Done {void call(String body)throws Exception;}
 void fetch(String url,Done done){new Thread(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setRequestProperty("User-Agent","WirdAndroid/0.2");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);String response=out.toString("UTF-8");runOnUiThread(()->{try{done.call(response);}catch(Exception e){toast("تعذّر قراءة البيانات");}});}}catch(Exception e){runOnUiThread(()->toast("تعذّر الاتصال بالمصدر"));}}).start();}
 void loadPage(){fetch("https://api.alquran.cloud/v1/page/"+page+"/quran-uthmani",s->{JSONObject obj=new JSONObject(s);JSONArray a=obj.getJSONObject("data").getJSONArray("ayahs");StringBuilder b=new StringBuilder();for(int i=0;i<a.length();i++){JSONObject v=a.getJSONObject(i);b.append(v.getString("text")).append("  ﴿").append(v.getInt("numberInSurah")).append("﴾\n\n");}base("المصحف • صفحة "+page);paragraph(b.toString());btn("الصفحة التالية",()->{page=Math.min(604,page+1);prefs.edit().putInt("page",page).apply();loadPage();});});}
 void audio(){base("الاستماع");card("القارئ: "+selectedReciter+"\nتلاوات السور تُبث من MP3Quran عبر الإنترنت.");for(String name:reciters)btn((name.equals(selectedReciter)?"✓ ":"")+name,()->{selectedReciter=name;prefs.edit().putString("reciter",name).apply();audio();});paragraph("رقم السورة: "+surah+" (من 1 إلى 114)");inputNumber("رقم السورة",surah,n->{if(n>=1&&n<=114){surah=n;audio();}else toast("السورة من 1 إلى 114");});btn("▶ تشغيل السورة",()->playAudio());btn("■ إيقاف التلاوة",()->stopAudio());}
 void playAudio(){fetch("https://mp3quran.net/api/v3/reciters?language=ar",s->{JSONArray a=new JSONObject(s).getJSONArray("reciters");for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String name=o.optString("name");if(name.equals(selectedReciter)|| (selectedReciter.equals("أحمد طالب بن حميد")&&name.contains("أحمد طالب")) || (selectedReciter.equals("محمد صديق المنشاوي")&&name.contains("المنشاوي")) || (selectedReciter.equals("محمود خليل الحصري")&&name.contains("الحصري")) || (selectedReciter.equals("علي جابر")&&name.contains("علي جابر"))){JSONArray m=o.getJSONArray("moshaf");for(int j=0;j<m.length();j++){JSONObject item=m.getJSONObject(j);String list=","+item.optString("surah_list")+",";if(list.contains(","+surah+",")){String url=item.getString("server")+String.format(java.util.Locale.US,"%03d.mp3",surah);stopAudio();try{player=new MediaPlayer();player.setDataSource(url);player.setOnPreparedListener(p->{p.start();toast("بدأ تشغيل التلاوة");});player.setOnErrorListener((p,w,x)->{toast("تعذر تشغيل التسجيل");return true;});player.prepareAsync();}catch(Exception e){toast("تعذر إعداد المشغل");}return;}}toast("هذه السورة غير متوفرة للقارئ في المصدر");return;}}toast("لم يُعثر على القارئ في المصدر");});}
 void stopAudio(){if(player!=null){try{player.stop();player.release();}catch(Exception ignored){}player=null;}}
 void tafsir(){base("تفسير ابن كثير");card("التفسير العربي لابن كثير يحتاج إلى مصدر مرخّص أو واجهة API معتمدة قبل دمجه كاملاً داخل التطبيق.\n\nيمكنك الآن فتح تفسير الآية عبر موقع القرآن الكريم، لكن هذا ليس تفسيراً مدمجاً دون إنترنت.");btn("افتح موقع القرآن الكريم والتفاسير",()->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://quran.com/ar/tafsirs"))));}
 void wisdom(){base("زاد القلب");card("﴿وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ﴾\nسورة القمر: 17");card("﴿فَإِنَّ مَعَ الْعُسْرِ يُسْرًا﴾\nسورة الشرح: 5");paragraph("سيُضاف هنا كلام ابن الجوزي وابن تيمية وابن القيم والحسن البصري بعد التحقق من نصوصه ومراجعها. لن ننسب أقوالاً غير موثقة.");}
 @Override protected void onDestroy(){stopAudio();super.onDestroy();}
}
